100→/**
101→ * Test-login endpoint flow that bypasses Core Kit entirely.
102→ *
103→ * 1. Calls POST /auth/test-login -> tokens + deterministic secp256k1 keypair
104→ * 2. Handles vault init/load using @cipherbox/crypto in Node.js
105→ * 3. Injects all state into Zustand stores via page.evaluate
106→ * 4. Navigates to /files
107→ *
108→ * Returns the auth state so callers can manage per-account state
109→ * (e.g., for multi-account sharing tests).
110→ */
111→export async function loginViaTestEndpoint(page: Page, email: string): Promise<TestAuthState> {
112→  const apiBase = process.env.API_BASE_URL || 'http://localhost:3000';
113→  const secret = process.env.TEST_LOGIN_SECRET!;
114→
115→  // 1. Authenticate via test-login endpoint
116→  const loginResponse = await page.request.post(`${apiBase}/auth/test-login`, {
117→    data: { email, secret },
118→  });
119→
120→  if (!loginResponse.ok()) {
121→    const body = await loginResponse.text();
122→    throw new Error(`Test login failed (${loginResponse.status()}): ${body}`);
123→  }
124→
125→  const { accessToken, refreshToken, publicKeyHex, privateKeyHex } = await loginResponse.json();
126→  const publicKey = hexToBytes(publicKeyHex);
127→  const privateKey = hexToBytes(privateKeyHex);
128→
129→  // 2. Handle vault: load existing or initialize new
130→  const vaultResponse = await page.request.get(`${apiBase}/vault`, {
131→    headers: { Authorization: `Bearer ${accessToken}` },
132→  });
133→
134→  let vaultId: string;
135→  let rootFolderKey: Uint8Array;
136→  let rootIpnsPrivateKey: Uint8Array;
137→  let rootIpnsName: string;
138→
139→  if (vaultResponse.ok()) {
140→    // Existing vault — decrypt keys
141→    const vault = await vaultResponse.json();
142→    vaultId = vault.id;
143→    rootIpnsName = vault.rootIpnsName;
144→
145→    const decrypted = await decryptVaultKeys(
146→      {
147→        encryptedRootFolderKey: hexToBytes(vault.encryptedRootFolderKey),
148→        encryptedIpnsPrivateKey: hexToBytes(vault.encryptedRootIpnsPrivateKey),
149→      },
150→      privateKey
151→    );
152→
153→    rootFolderKey = decrypted.rootFolderKey;
154→    rootIpnsPrivateKey = decrypted.rootIpnsKeypair.privateKey;
155→  } else {
156→    // New user — initialize vault
157→    const newVault = await initializeVault(privateKey);
158→    const encrypted = await encryptVaultKeys(newVault, publicKey);
159→    rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);
160→
161→    const initResponse = await page.request.post(`${apiBase}/vault/init`, {
162→      headers: { Authorization: `Bearer ${accessToken}` },
163→      data: {
164→        ownerPublicKey: publicKeyHex,
165→        encryptedRootFolderKey: bytesToHex(encrypted.encryptedRootFolderKey),
166→        encryptedRootIpnsPrivateKey: bytesToHex(encrypted.encryptedIpnsPrivateKey),
167→        rootIpnsName,
168→      },
169→    });
170→
171→    if (!initResponse.ok()) {
172→      const body = await initResponse.text();
173→      throw new Error(`Vault init failed (${initResponse.status()}): ${body}`);
174→    }
175→
176→    const initResult = await initResponse.json();
177→    vaultId = initResult.id;
178→    rootFolderKey = newVault.rootFolderKey;
179→    rootIpnsPrivateKey = newVault.rootIpnsKeypair.privateKey;
180→  }
181→
182→  // Derive IPNS public key from private key (deterministic Ed25519 derivation)
183→  const rootIpnsPublicKey = await ed.getPublicKeyAsync(rootIpnsPrivateKey);
184→
185→  const authState: TestAuthState = {
186→    accessToken,
187→    email,
188→    publicKeyHex,
189→    publicKeyArr: Array.from(publicKey),
190→    privateKeyArr: Array.from(privateKey),
191→    rootFolderKeyArr: Array.from(rootFolderKey),
192→    rootIpnsPublicKeyArr: Array.from(rootIpnsPublicKey),
193→    rootIpnsPrivateKeyArr: Array.from(rootIpnsPrivateKey),
194→    rootIpnsName,
195→    vaultId,
196→  };
197→
198→  // 2.5. Set refresh token cookie in the browser context for session persistence
199→  const url = new URL(apiBase);
200→  await page.context().addCookies([
201→    {
202→      name: 'refresh_token',
203→      value: refreshToken,
204→      domain: url.hostname,
205→      path: '/auth',
206→      httpOnly: true,
207→      secure: false, // dev mode
208→      sameSite: 'Lax',
209→    },
210→  ]);
211→
212→  // 3. Navigate to app so we can inject state into Zustand stores
213→  await page.goto('/');
214→
215→  await injectAuthState(page, authState);
216→
217→  // 5. Navigate to files page via hash router (no full reload — preserves Zustand state)
218→  await page.evaluate(() => {
219→    window.location.hash = '#/files';
220→  });
221→  await page.waitForURL('**/files', { timeout: 30000 });
222→
223→  return authState;
224→}
