270→/**
271→ * Re-inject test auth state after a page reload.
272→ * Since test-login bypasses Core Kit, there's no persistent session —
273→ * this function restores Zustand stores from the cached first login,
274→ * refreshes the access token via the HTTP-only cookie, then navigates
275→ * to /files.
276→ *
277→ * Call this after page.reload() in tests that use the test-login flow.
278→ * For tests using the real Core Kit flow, this is a no-op (Core Kit
279→ * auto-restores its session).
280→ *
281→ * Accepts explicit state for multi-account tests. Falls back to
282→ * singleton cache for backward compat with existing tests.
283→ */
284→export async function reinjectTestAuthAfterReload(
285→  page: Page,
286→  state?: TestAuthState
287→): Promise<void> {
288→  const authState = state ?? cachedTestAuthState;
289→
290→  // If not using test-login, Core Kit handles session restore
291→  if (!process.env.TEST_LOGIN_SECRET || !authState) return;
292→
293→  // Try to refresh the access token via the cookie
294→  const apiBase = process.env.API_BASE_URL || 'http://localhost:3000';
295→  const refreshResponse = await page.request.post(`${apiBase}/auth/refresh`);
296→
297→  if (refreshResponse.ok()) {
298→    const { accessToken, email } = await refreshResponse.json();
299→    authState.accessToken = accessToken;
300→    if (email) authState.email = email;
301→  }
302→
303→  await injectAuthState(page, authState);
304→
305→  // Navigate to files via hash router
306→  await page.evaluate(() => {
307→    window.location.hash = '#/files';
308→  });
309→  await page.waitForURL('**/files', { timeout: 30000 });
310→}
