        if (!stores?.vault) return false;
        const vault = stores.vault.getState();
        return !!vault.rootFolderKey && !!vault.rootIpnsKeypair && !!vault.rootIpnsName;
      },
      { timeout: 30_000 }
    );
  }

  return result;
}

